  "Logo atualizado.": { fr: "Logo mis à jour.", es: "Logo actualizado." },
  "Logo removido.": { fr: "Logo supprimé.", es: "Logo eliminado." },
  "PNG ou JPG, até": { fr: "PNG ou JPG, jusqu'à", es: "PNG o JPG, hasta" },
