  "Não consegui completar essa ação. Tente de novo.": {
    fr: "Impossible de terminer cette action. Réessayez.",
    es: "No pude completar esa acción. Intenta de nuevo.",
  },
  "Nome do funil — ex.: Consultas, Obras, Matrículas": {
    fr: "Nom de l'entonnoir — ex. : Consultations, Chantiers, Inscriptions",
    es: "Nombre del embudo — ej.: Consultas, Obras, Matrículas",
  },
  "Nome do novo funil": { fr: "Nom du nouvel entonnoir", es: "Nombre del nuevo embudo" },
  "Criar funil": { fr: "Créer l'entonnoir", es: "Crear embudo" },
